struct picture_format { int format; int width; int height; };
struct picture { int needs_fg; struct picture_format *f_grain; struct picture_format *f; };

void alloc_picture(struct picture *pic) {
    /* 
     * EXPLOIT MECHANISM:
     * The condition checks pic->needs_fg but does not verify if pic->f_grain is allocated.
     * If an attacker can manipulate decoder state to set needs_fg=true while f_grain remains NULL,
     * the subsequent dereference triggers a NULL pointer dereference (segfault), causing DoS.
     */
    if (pic->needs_fg) {
        pic->f_grain->format = pic->f->format;
        pic->f_grain->width = pic->f->width;
        pic->f_grain->height = pic->f->height;
    }
}

