    AVCodecParameters *codecpar; /* Not initialized by avformat_new_stream */
} AVStream;

typedef struct {
    AVStream *streams[1];
} AVFormatContext;

/* Simulates the vulnerable code path in libavformat/mov.c */
void ff_add_attached_pic_vulnerable(AVFormatContext *fmt, AVCodecID id) {
    /* 1. Simulate avformat_new_stream: allocates stream but leaves codecpar as NULL */
    AVStream *st = malloc(sizeof(AVStream));
    st->codecpar = NULL; /* Missing initialization/allocation */

    fmt->streams[0] = st;

    /* 2. VULNERABILITY: Direct dereference without NULL check or avcodec_parameters_alloc() */
    /* In a real FFmpeg build, this line triggers a segmentation fault (DoS) */
    st->codecpar->codec_id = id;
}

int main(void) {
    AVFormatContext *fmt = malloc(sizeof(AVFormatContext));
    /* Triggered by parsing a malicious MOV file containing a 'covr' atom */
    ff_add_attached_pic_vulnerable(fmt, AV_CODEC_ID_AAC);
    return 0;
}

